"""Human-controlled exact generated bytes, never inferred release clearance."""

from uuid import uuid4

import pytest
from pydantic import ValidationError

from dtvp.knowledge.documents import (
    DocumentInput,
    DocumentReviewInput,
    document_status,
    list_documents,
    register_document,
    review_document,
)
from dtvp.knowledge.issued_exports import issue_export
from dtvp.knowledge.journal import Conflict, Ref, Update
from dtvp.knowledge.workspace import load_sections
from dtvp.storage import canonical, digest
from tests.test_knowledge_agentyzer import VERSION
from tests.test_knowledge_issued_exports import inputs, publish  # noqa: F401


def head(journal):
    return journal.resolve(Ref(project_id="product", name=VERSION))


def allow(capability):
    assert capability in {"documentary_assess", "documentary_approve"}


def register(env, *, actor="author", submit=True, raw=b"# Exact generated report\n", **changes):
    journal, _, issued = env
    status = document_status(journal, head(journal), changes.get("document_id", "architecture"))
    fields = dict(
        request_id=str(uuid4()),
        expected=head(journal),
        expected_revision=status["document"]["revision"] if status else None,
        document_id="architecture",
        issued_receipt_sha=issued["receipt_sha256"],
        renderer={"name": "generator", "version": "unknown-future-renderer"},
        configuration={"template": "audited-template", "locale": "de"},
        title="Architecture evidence",
        purpose="architecture",
        rationale="Generated from pinned input",
        filename="architecture.md",
        media_type="text/markdown",
    )
    fields.update(changes)
    data = DocumentInput(**fields)
    return register_document(
        journal, "product", VERSION, actor, data, raw, submit=submit, authorize=allow
    ), data


def review(env, *, actor="reviewer", **changes):
    journal, _, _ = env
    status = document_status(journal, head(journal), "architecture")
    fields = dict(
        request_id=str(uuid4()),
        expected=head(journal),
        document_id="architecture",
        revision=status["document"]["revision"],
        action="approve",
        rationale="Reviewed exact generated content",
    )
    fields.update(changes)
    data = DocumentReviewInput(**fields)
    return review_document(journal, "product", VERSION, actor, data, authorize=allow), data


@pytest.fixture
def documents(inputs):  # noqa: F811
    journal, state, _ = inputs
    issued = issue_export(
        journal, project_id="product", actor_id="issuer", state=state, kind="knowledge-bundle"
    )
    return journal, state, issued


def test_exact_artifact_configuration_provenance_and_independent_approval(documents):
    journal, state, issued = documents
    raw = b"\x00opaque exact generated bytes\xff\r\n"
    register(documents, raw=raw)
    current = document_status(journal, head(journal), "architecture")
    payload = current["document"]["payload"]
    assert journal.objects.read(payload["artifact_sha256"]) == raw
    assert journal.objects.read(payload["configuration_sha256"]) == canonical(
        {"template": "audited-template", "locale": "de"}
    )
    assert payload["source_state"] == state and payload["issued_state"] == issued["issuance_state"]
    assert payload["bundle_sha256"] == issued["files"]["bundle.json"]["sha256"]
    assert current["status"] == "submitted" and current["source_current"]
    with pytest.raises(PermissionError, match="independent"):
        review(documents, actor="author")
    review(documents)
    status = document_status(journal, head(journal), "architecture")
    assert status["status"] == "approved" and status["approved_source_current"]
    assert status["review"]["source_current_at_review"]
    assert payload["artifact_sha256"] in journal.state(head(journal)).artifacts
    assert len(status["limitations"]) == 3


def test_prior_approved_pin_survives_pending_draft_and_tags_are_stable(documents):
    journal, _, _ = documents
    register(documents)
    review(documents)
    approved_head = head(journal)
    old = document_status(journal, approved_head, "architecture")
    register(documents, submit=False, raw=b"new draft")
    pending = document_status(journal, head(journal), "architecture")
    assert pending["status"] == "approved" and pending["pending"]
    assert pending["approved_document"]["revision"] == old["document"]["revision"]
    assert pending["document"]["revision"] != old["document"]["revision"]
    assert pending["approved_source_current"] and pending["source_current"]
    assert document_status(journal, approved_head, "architecture") == old
    with pytest.raises(Conflict, match="submitted"):
        review(documents)


def test_historical_approval_requires_acknowledgement_and_never_becomes_current(documents):
    journal, _, _ = documents
    register(documents)
    previous = head(journal)
    sections = load_sections(journal, previous)
    sections["inventory"]["root"]["version"] = "materially-different"
    publish(journal, previous, sections)
    assert not document_status(journal, head(journal), "architecture")["source_current"]
    with pytest.raises(Conflict, match="Historical"):
        review(documents)
    review(documents, acknowledge_historical=True)
    status = document_status(journal, head(journal), "architecture")
    assert status["status"] == "approved" and not status["approved_source_current"]
    assert status["review"]["acknowledge_historical"]
    assert not status["review"]["source_current_at_review"]


def test_author_only_revisions_and_explicit_separate_document_ids(documents):
    journal, _, _ = documents
    register(documents)
    before = journal.head()
    with pytest.raises(PermissionError, match="author"):
        register(documents, actor="other-author")
    assert journal.head() == before
    register(documents, actor="other-author", document_id="separate-report")
    assert list_documents(journal, head(journal), limit=1)["total"] == 2
    assert list_documents(journal, head(journal), offset=1, limit=1)["next_offset"] is None
    assert document_status(journal, head(journal), "absent") is None


def test_replays_precede_head_checks_and_different_bytes_conflict(documents):
    journal, _, _ = documents
    receipt, data = register(documents)
    assert (
        register_document(
            journal,
            "product",
            VERSION,
            "author",
            data,
            b"# Exact generated report\n",
            submit=True,
            authorize=allow,
        )
        == receipt
    )
    with pytest.raises(Conflict, match="different input"):
        register_document(
            journal, "product", VERSION, "author", data, b"changed", submit=True, authorize=allow
        )
    review_receipt, review_data = review(documents)
    assert (
        review_document(journal, "product", VERSION, "reviewer", review_data, authorize=allow)
        == review_receipt
    )
    stale = data.model_copy(update={"request_id": str(uuid4())})
    with pytest.raises(Conflict, match="version changed"):
        register_document(
            journal, "product", VERSION, "author", stale, b"x", submit=True, authorize=allow
        )
    with pytest.raises(Conflict, match="revision changed"):
        register(documents, expected_revision=None)


def test_cas_and_permission_failure_publish_nothing(documents, monkeypatch):
    journal, _, _ = documents

    def deny(cap):
        raise PermissionError(cap)

    _, data = register(documents, submit=False)
    before = journal.head()
    with pytest.raises(PermissionError, match="documentary_assess"):
        register_document(
            journal, "product", VERSION, "author", data, b"x", submit=False, authorize=deny
        )
    assert journal.head() == before
    native = type(journal).publish
    raced = []

    def race(self, **kwargs):
        if not raced:
            raced.append(True)
            parent = head(journal)
            sections = load_sections(journal, parent)
            sections["history"]["fixture"] = {"concurrent": True}
            publish(journal, parent, sections)
        return native(self, **kwargs)

    monkeypatch.setattr(type(journal), "publish", race)
    with pytest.raises(Conflict, match="Branch changed"):
        register(documents)
    assert document_status(journal, head(journal), "architecture")["document"]["stage"] == "draft"


def test_unissued_wrong_consumer_or_other_version_is_rejected(documents):
    journal, _, _ = documents
    with pytest.raises(ValueError, match="issued knowledge bundle"):
        register(documents, issued_receipt_sha="f" * 64)
    from tests.test_knowledge_agentyzer import derive

    source = derive(journal, head(journal))
    specialist = issue_export(
        journal,
        project_id="product",
        actor_id="issuer",
        state=head(journal),
        kind="agentyzer-input",
        payload=source,
    )
    with pytest.raises(ValueError, match="issued knowledge bundle"):
        register(documents, issued_receipt_sha=specialist["receipt_sha256"])
    with pytest.raises(ValueError, match="1 byte"):
        register(documents, raw=b"")
    with pytest.raises(ValidationError):
        register(documents, filename="../report.md")


def test_source_facts_and_license_decisions_remain_separate_from_document_approval(documents):
    journal, _, _ = documents
    original = load_sections(journal, head(journal))
    register(documents, purpose="combined")
    review(documents)
    after = load_sections(journal, head(journal))
    assert {k: v for k, v in after.items() if k != "history"} == {
        k: v for k, v in original.items() if k != "history"
    }
    assert all(after["history"][key] == value for key, value in original["history"].items())


def test_unknown_serializer_is_archived_without_current_serialization_and_tag_remains_frozen(
    documents, monkeypatch
):
    journal, state, issued = documents
    monkeypatch.setattr(
        "dtvp.knowledge.issued_exports.export_bytes",
        lambda *a: pytest.fail("Must not reserialize issued inputs"),
    )
    monkeypatch.setattr("dtvp.knowledge.issued_exports.SERIALIZERS", {})
    register(documents)
    assert issued["issuance_state"] in journal.state(head(journal)).parents
    review(documents)
    tagged = head(journal)
    ref = Ref(project_id="product", kind="tag", name="release-7.1.1")
    journal.publish(
        request_id="document-tag",
        fingerprint=digest(b"tag"),
        updates=[Update(ref=ref, expected=None, target=tagged)],
    )
    old = document_status(journal, tagged, "architecture")
    sections = load_sections(journal, tagged)
    sections["history"]["license-disposition:component"] = {"disposition": "prohibited"}
    publish(journal, tagged, sections)
    assert not document_status(journal, head(journal), "architecture")["source_current"]
    assert document_status(journal, journal.resolve(ref), "architecture") == old
    assert old["approved_source_current"]


def test_review_revision_cas_and_changes_requested_are_explicit(documents):
    journal, _, _ = documents
    register(documents)
    first = document_status(journal, head(journal), "architecture")["document"]["revision"]
    register(documents, raw=b"next submitted revision")
    before = journal.head()
    with pytest.raises(Conflict, match="exact current"):
        review(documents, revision=first)
    assert journal.head() == before
    review(documents, action="request_changes")
    status = document_status(journal, head(journal), "architecture")
    assert status["status"] == "changes_requested" and status["approved_document"] is None


def test_forked_version_and_new_document_cannot_inherit_prior_version_approval(documents):
    journal, _, _ = documents
    _, data = register(documents)
    review(documents)
    source = head(journal)
    inherited = document_status(journal, source, "architecture")
    fork = publish(journal, source, load_sections(journal, source), version="7.1.2")
    old = document_status(journal, fork, "architecture")
    assert old["status"] == "out_of_scope" and old["approved_document"] is None
    assert old["historical_review"]["revision"] == inherited["review"]["revision"]
    issued = issue_export(
        journal, project_id="product", actor_id="issuer", state=fork, kind="knowledge-bundle"
    )
    adopted = data.model_copy(
        update={
            "request_id": str(uuid4()),
            "expected": fork,
            "expected_revision": old["document"]["revision"],
            "issued_receipt_sha": issued["receipt_sha256"],
        }
    )
    register_document(
        journal,
        "product",
        "7.1.2",
        "author",
        adopted,
        b"New version report",
        submit=True,
        authorize=allow,
    )
    current = journal.resolve(Ref(project_id="product", name="7.1.2"))
    status = document_status(journal, current, "architecture")
    assert status["status"] == "submitted" and status["source_current"]
    assert not status["pending"] and status["approved_document"] is None
    assert status["review"] is None and status["historical_review"]["payload"]["version"] == VERSION
